// Encode returns m's wire encoding: its message id, then its fields.
func Encode(m Message) []byte { return AppendMessage(nil, m) }

// Decode reads exactly one message.
func Decode(b []byte) (Message, error) {
	r := wire.NewReader(b)
	m := ReadMessage(r)
	if err := r.Done(); err != nil {
		return nil, err
	}
	if m == nil {
		return nil, wire.ErrVariant
	}
	return m, nil
}
